    steps: [['Load at Startup', 'Use FastAPI `lifespan` or module singleton'], ['Pick Device', 'Auto-detect CUDA GPU vs Apple MPS vs CPU'], ['Pin Local Cache', 'Bake weights into Docker image or volume'], ['Warm Up Call', 'Run 1 dummy inference before serving traffic']],
